const LEVELS=window.MAGIC_FOREST_LEVELS,KEY='magicForestSaveV1';
let save=JSON.parse(localStorage.getItem(KEY)||'null')||{unlocked:1,stars:{},items:[],crystals:0,sound:true};
const app=document.querySelector('#app');let audio;
function persist(){localStorage.setItem(KEY,JSON.stringify(save))}
function tone(freq=520,d=.12){if(!save.sound)return;audio||=new(window.AudioContext||window.webkitAudioContext)();const o=audio.createOscillator(),g=audio.createGain();o.frequency.value=freq;o.type='sine';g.gain.setValueAtTime(.08,audio.currentTime);g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+d);o.connect(g).connect(audio.destination);o.start();o.stop(audio.currentTime+d)}
function headerBar(back=false){return `<header class="topbar">${back?'<button class="icon-btn" data-go="map" aria-label="กลับแผนที่">‹</button>':''}<div class="brand">✦ ผจญภัยในป่าเวทมนตร์</div><div class="pill">💎 <b>${save.crystals}</b></div><button class="icon-btn" data-sound aria-label="เปิดหรือปิดเสียง">${save.sound?'🔊':'🔇'}</button></header>`}
function bindCommon(){document.querySelector('[data-sound]')?.addEventListener('click',e=>{save.sound=!save.sound;persist();e.currentTarget.textContent=save.sound?'🔊':'🔇';tone()});document.querySelectorAll('[data-go="map"]').forEach(b=>b.onclick=map)}
function home(){app.innerHTML=`<section class="screen">${headerBar()}<div class="hero"><div class="intro"><div class="eyebrow">WORLD 1 · ป่าแห่งตัวเลข</div><h1>ปลุกพลัง<br>แห่งตัวเลข</h1><p>ร่วมเดินทางกับแบมแบม ชิป และฟลัฟฟี่ ไขปริศนาที่ทำให้คณิตศาสตร์เปลี่ยนโลกได้จริง</p><div class="actions"><button class="primary" id="start">${save.unlocked>1?'เล่นต่อ ด่าน '+save.unlocked:'เริ่มการผจญภัย'}</button><button class="secondary" id="ar">◉ โลก AR</button></div><div class="inventory">${save.items.length?save.items.map(x=>`<span class="item">${x}</span>`).join(''):'<span class="item">กระเป๋ายังว่าง</span>'}</div></div><div class="companions" aria-label="แบมแบม ชิป และฟลัฟฟี่"><div class="avatar">🧒🏻</div><div class="avatar">🐿️</div><div class="avatar">🐇</div></div></div></section>`;bindCommon();start.onclick=map;ar.onclick=()=>toast('โลก AR จะเปิดในเฟสถัดไป — ไอเท็มที่สะสมไว้จะนำไปใช้ได้!')}
function map(){app.innerHTML=`<section class="screen">${headerBar()}<div class="map-wrap"><div class="map-head"><div><div class="eyebrow">แผนที่การผจญภัย</div><h1>World 1 · ป่าเวทมนตร์</h1><p>สำรวจ แก้ปริศนา และช่วยสัตว์วิเศษ</p></div><button class="secondary" id="reset">เริ่มใหม่</button></div><div class="stage-grid">${LEVELS.map(l=>{const locked=l.id>save.unlocked,stars=save.stars[l.id]||0;return `<button class="stage ${locked?'locked':''} ${stars?'done':''}" data-level="${l.id}" ${locked?'disabled':''}><span class="num">ด่าน ${l.id} ${locked?'· 🔒':''}</span><span class="emoji">${l.icon}</span><h2>${l.title}</h2><p>${l.mechanic}</p><span class="stars">${'★'.repeat(stars)}${'☆'.repeat(3-stars)}</span></button>`}).join('')}</div></div></section>`;bindCommon();document.querySelectorAll('[data-level]').forEach(b=>b.onclick=()=>play(+b.dataset.level));reset.onclick=()=>{if(confirm('ลบความคืบหน้าและเริ่มใหม่หรือไม่?')){localStorage.removeItem(KEY);save={unlocked:1,stars:{},items:[],crystals:0,sound:true};map()}}}
function play(id){const l=LEVELS[id-1];let tries=0,value=l.type==='counter'?600:'',digits='';app.innerHTML=`<section class="play">${headerBar(true)}<div class="play-area"><article class="mission"><div class="eyebrow">ด่าน ${l.id} จาก ${LEVELS.length}</div><div class="scene-icon">${l.icon}</div><h1>${l.title}</h1><p class="story">${l.story}</p><div class="prompt">${l.prompt}</div><div class="puzzle" id="puzzle"></div><div class="feedback" id="feedback"></div></article></div></section>`;bindCommon();const p=document.querySelector('#puzzle'),fb=document.querySelector('#feedback');const check=v=>{tries++;if(String(v)===String(l.answer)){tone(740,.25);finish(l,tries)}else{tone(180,.18);fb.textContent=tries===1?'เกือบแล้ว! ลองแยกหลักร้อย หลักสิบ และหลักหน่วยดู':'ชิปกระซิบ: ลองคำนวณทีละส่วน แล้วลองอีกครั้ง';navigator.vibrate?.(60)}};
if(l.type==='drag'){p.innerHTML=l.choices.map(x=>`<button draggable="true" class="tile" data-v="${x}">${x}</button>`).join('')+'<div class="slot" tabindex="0">วางที่นี่</div>';const slot=p.querySelector('.slot');p.querySelectorAll('.tile').forEach(t=>{t.ondragstart=e=>e.dataTransfer.setData('text',t.dataset.v);t.onclick=()=>check(t.dataset.v)});slot.ondragover=e=>{e.preventDefault();slot.classList.add('over')};slot.ondragleave=()=>slot.classList.remove('over');slot.ondrop=e=>{e.preventDefault();slot.classList.remove('over');check(e.dataTransfer.getData('text'))}}
if(l.type==='digits'){p.innerHTML='<div class="slot" id="display">_ _ _</div>'+l.choices.map(x=>`<button class="tile" data-v="${x}">${x}</button>`).join('')+'<button class="choice" id="clear">ล้าง</button>';p.querySelectorAll('.tile').forEach(t=>t.onclick=()=>{if(digits.length<3){digits+=t.dataset.v;display.textContent=digits.split('').join(' ');tone(420+digits.length*80);if(digits.length===3)setTimeout(()=>check(digits),180)}});clear.onclick=()=>{digits='';display.textContent='_ _ _'}}
if(l.type==='counter'){p.innerHTML=`<div class="counter"><button id="minus">−</button><strong id="val">${value}</strong><button id="plus">+</button></div><button class="primary" id="cast">ร่ายเวท</button>`;minus.onclick=()=>{value--;val.textContent=value;tone(340)};plus.onclick=()=>{value++;val.textContent=value;tone(520)};cast.onclick=()=>check(value)}
if(l.type==='choice'){p.innerHTML=l.choices.map(x=>`<button class="choice" data-v="${x}">${x}</button>`).join('');p.querySelectorAll('.choice').forEach(c=>c.onclick=()=>check(c.dataset.v))}}
function finish(l,tries){const stars=tries===1?3:tries<=3?2:1;save.stars[l.id]=Math.max(save.stars[l.id]||0,stars);save.unlocked=Math.min(LEVELS.length,Math.max(save.unlocked,l.id+1));if(!save.items.includes(l.item+' '+l.reward)){save.items.push(l.item+' '+l.reward);save.crystals+=10}persist();app.insertAdjacentHTML('beforeend',`<div class="reward"><div class="reward-card"><div class="reward-burst">${l.item}</div><div class="eyebrow">${'★'.repeat(stars)}${'☆'.repeat(3-stars)}</div><h2>เวทมนตร์สำเร็จ!</h2><p>ได้รับ “${l.reward}” และผลึกเวทมนตร์ 10 ชิ้น</p><button class="primary" id="next">${l.id===LEVELS.length?'ดูแผนที่':'ไปด่านถัดไป'}</button></div></div>`);next.onclick=()=>l.id<LEVELS.length?play(l.id+1):map()}
function toast(msg){const t=document.createElement('div');t.className='toast';t.textContent=msg;document.body.append(t);setTimeout(()=>t.remove(),3200)}
home();
